select sub.REGIST_SEQNO registSeqno, sub.PROD_ID prodId,
info.REG_CODE issuePartyId, /*发行机构代码*/
sub.ISSUE_PARTY_ID issuePartyId,
sub.SINGLE_TOTAL singleTotal, sub.LEGAL_TOTAL legalTotal, sub.UNLEGAL_TOTAL unlegalTotal, sub.SUBSCRIBE_CCY_AMT subscribeCcyAmt, sub.SALE_AREA_AMT saleAreaAmt, sub.TOTAL_AMT totalAmt, sub.RAISE_QTY raiseQty, sub.IS_CONSIGN isConsign, sub.CONSIGN_AMT consignAmt, sub.REMARK remark, sub.SEND_STATUS sendStatus, sub.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, sub.STATUS_DATE statusDate, sub.STATUS status, sub.CREATE_USER createUser, sub.CREATE_DEPT createDept, sub.CREATE_TIME createTime, sub.UPDATE_USER updateUser, sub.UPDATE_TIME updateTime, sub.SUBMIT_TIME submitTime, sub.CHB_SUBMIT_DEADLINE chbSubmitDeadline, sub.SUBMIT_DEADLINE submitDeadline, sub.ORG_CODE orgCode, sub.DEPT_CODE deptCode, info.PROD_NAME prodName, code.REG_CODE regCode, sub.SUMIT_SEQ sumitSeq, sub.PROD_REGIST_CODE prodRegistCode, sub.BUSI_ACCT_NO busiAcctNo, sub.ACCT_NAME acctName
from CHB_PRD_RAISETOT_SUB sub left join chb_prd_baseinfo info on info.prod_id=sub.prod_id and info.status != 'D' left join CHB_PRDRESIST_CODE code on code.prodid=sub.prod_id where 1=1
and sub.IS_CONSIGN = #{isConsign,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
and DATE_FORMAT(sub.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitendDateStart}
and DATE_FORMAT(sub.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitendDateEnd}
and DATE_FORMAT(sub.STATUS_DATE,'%Y-%m-%d') >= #{dataDateStart}
and DATE_FORMAT(sub.STATUS_DATE,'%Y-%m-%d') <= #{dataDateEnd}
and DATE_FORMAT(sub.SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart}
and DATE_FORMAT(sub.SUBMIT_TIME,'%Y-%m-%d') <= #{submitDateEnd}
and DATE_FORMAT(info.VDATE,'%Y-%m-%d') >= #{vdateStart}
and DATE_FORMAT(info.VDATE,'%Y-%m-%d') <= #{vdateEnd}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
order by sub.SUBMIT_DEADLINE

select sub.* from ( select sub.REGIST_SEQNO, sub.PROD_ID, sub.ISSUE_PARTY_ID, sub.SINGLE_TOTAL, sub.LEGAL_TOTAL, sub.UNLEGAL_TOTAL, sub.SUBSCRIBE_CCY_AMT, sub.SALE_AREA_AMT, sub.TOTAL_AMT, sub.RAISE_QTY, sub.IS_CONSIGN, sub.CONSIGN_AMT, sub.REMARK, sub.SEND_STATUS, sub.SUBMIT_FEEDBACK_STATUS, sub.STATUS_DATE, sub.STATUS, sub.CREATE_USER, sub.CREATE_DEPT, sub.CREATE_TIME, sub.UPDATE_USER, sub.UPDATE_TIME, sub.SUBMIT_TIME, sub.CHB_SUBMIT_DEADLINE, sub.SUBMIT_DEADLINE, sub.ORG_CODE, sub.DEPT_CODE,info.prod_name prodname,code.reg_code, sub.PROD_REGIST_CODE,sub.ACCT_NAME,sub.BUSI_ACCT_NO
from CHB_PRD_RAISETOT_SUB sub left join chb_prd_baseinfo info on info.prod_id=sub.prod_id left join CHB_PRDRESIST_CODE code on code.prodid=sub.prod_id where 1=1 and sub.TOTAL_AMT>0 and info.OPERATE_MODE in('01','02')
#{items.registSeqno,jdbcType=VARCHAR}
union all select sub.REGIST_SEQNO, sub.PROD_ID, sub.ISSUE_PARTY_ID, sub.SINGLE_TOTAL, sub.LEGAL_TOTAL, sub.UNLEGAL_TOTAL, sub.SUBSCRIBE_CCY_AMT, sub.SALE_AREA_AMT, sub.TOTAL_AMT, sub.RAISE_QTY, sub.IS_CONSIGN, sub.CONSIGN_AMT, sub.REMARK, sub.SEND_STATUS, sub.SUBMIT_FEEDBACK_STATUS, sub.STATUS_DATE, sub.STATUS, sub.CREATE_USER, sub.CREATE_DEPT, sub.CREATE_TIME, sub.UPDATE_USER, sub.UPDATE_TIME, sub.SUBMIT_TIME, sub.CHB_SUBMIT_DEADLINE, sub.SUBMIT_DEADLINE, sub.ORG_CODE, sub.DEPT_CODE,info.prod_name prodname,code.reg_code, sub.PROD_REGIST_CODE,sub.ACCT_NAME,sub.BUSI_ACCT_NO
from CHB_PRD_RAISETOT_SUB sub left join chb_prd_baseinfo info on info.prod_id=sub.prod_id left join CHB_PRDRESIST_CODE code on code.prodid=sub.prod_id where 1=1 and info.OPERATE_MODE in('03','04')
#{items.registSeqno,jdbcType=VARCHAR}
) sub order by sub.SUBMIT_DEADLINE

